"use client";
import type { Role } from "@rvr/contract";

export type Frame = "idle" | "working" | "found";

/** Pixel sprites from assets/avatars (generated by gen.py). Orchestrator is a 24px grid, the rest 16px. */
export function Sprite({ role, frame = "idle", className = "", style, title, scale = 1.5, onClick }: { role: Role; frame?: Frame; className?: string; style?: React.CSSProperties; title?: string; scale?: number; onClick?: () => void }) {
  const grid = role === "orchestrator" ? 24 : 16;
  const px = Math.round(grid * scale);
  return (
    <img src={`/avatars/${role}_${frame}.svg`} alt={title ?? role} title={title} className={`av ${className}`} width={px} height={px}
      style={{ width: px, height: px, cursor: onClick ? "pointer" : undefined, ...style }} draggable={false} onClick={onClick} />
  );
}
